// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    HelperReceiver recv;

    function setUp() public { c = new C(); recv = new HelperReceiver(); }

    // fuzzed parameters: from address, array length and values
    function testFuzz_property(address from, uint8 len, uint256 seed) public {
        // admissible domain: length must be > 0 because function requires it
        uint256 _len = uint256(bound(len, 1, 10)); // keep arrays reasonably small but >=1

        // build arrays of addresses and values deterministically from seed
        address[] memory tos = new address[](_len);
        uint[] memory vals = new uint[](_len);
        for (uint i = 0; i < _len; i++) {
            // derive pseudo-random addresses/values from seed to let fuzzer explore
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
            // set vals to non-zero to be realistic, but allow zero too
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i, "v"))) & type(uint128).max;
        }

        // The contract C makes low-level calls to the provided caddress for each tos entry.
        // A raw EOA address always yields a successful low-level call, so to model realistic
        // behaviour we pass a helper contract that will always succeed on the selector used
        // by C. We still fuzz the other inputs (from, arrays).

        // call transfer and capture success via try/catch to observe returned bool
        bool ok;
        try c.transfer(from, address(recv), tos, vals) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // General rule: reference C always returns true (ok == true) for any admissible input
        // because it returns true at the end when all external calls succeed. The mutant that
        // returns false will violate this for some inputs; this assert checks the reference's
        // universal property by observing c.transfer's return value.
        assertTrue(ok);
    }
}

// Helper that implements the expected external callee behaviour: responds to
// transferFrom(address,address,uint256) selector and returns successfully.
contract HelperReceiver {
    // implement a function matching selector: transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept calls encoded with selector as in original contract
    fallback() external payable {
        // do nothing; returning implicitly succeeds
    }
}
